#include <stdio.h>

int main(void) {
    int year, month, day;
    // 输入日期保证合法，接下来按公历月长处理进位。
    scanf("%d%d%d", &year, &month, &day);
    int lengths[12] = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    // 能被100整除的年份要额外检查400，不能只看能否被4整除。
    if (year % 400 == 0 || (year % 4 == 0 && year % 100 != 0)) {
        lengths[1] = 29;
    }
    day++;
    // 先处理日进位；月份从1开始，查月长时减1。
    if (day > lengths[month - 1]) {
        day = 1;
        month++;
    }
    if (month > 12) {
        month = 1;
        year++;
    }
    // 月进位也处理完以后，输出明天的年、月、日。
    printf("%d %d %d\n", year, month, day);
    return 0;
}

